#' Gemini LLM Service
#' Provides integration with Google Gemini API with rate limiting and caching.
#' @export
GeminiService <- R6::R6Class('GeminiService', private = list(config = NULL, initialized = FALSE, request_timestamps = c(), token_usage_minute = 0, token_usage_day = 0, cache = list()), public = list(initialize = function(config = NULL) { private <- config %||% list(api_key_env = 'GEMINI_API_KEY', model = 'gemini-3-flash-preview', temperature = 0.7, max_tokens = 8192, rate_limit_rpm = 15, rate_limit_tpm = 1000000, cache_ttl = 3600) }, initialize_service = function() { if (private) return(invisible(self)); api_key <- Sys.getenv(private); if (nchar(api_key) == 0) stop('API key not found'); private <- TRUE; return(invisible(self)) }, check_rate_limit = function(estimated_tokens = 1000) { now <- as.numeric(Sys.time()); one_minute_ago <- now - 60; private <- private[private > one_minute_ago]; if (length(private) >= private) return(FALSE); return(TRUE) }, record_request = function(tokens_used) { private <- c(private, as.numeric(Sys.time())); private <- private + tokens_used }, complete = function(prompt, system_prompt = NULL) { if (!private) self(); if (!self(nchar(prompt) %/% 4)) stop('Rate limit exceeded'); api_key <- Sys.getenv(private); url <- paste0('https://generativelanguage.googleapis.com/v1beta/models/', private, ':generateContent'); body <- list(contents = list(list(role = 'user', parts = list(list(text = prompt))))); response <- httr2::request(url) |> httr2::req_headers('Content-Type' = 'application/json', 'x-goog-api-key' = api_key) |> httr2::req_body_json(body) |> httr2::req_perform(); result <- httr2::resp_body_json(response); response_text <- result[[1]][[1]]; self(nchar(response_text) %/% 4); private[[digest::digest(list(prompt = prompt))]] <- response_text; return(response_text) }, analyze_with_context = function(analysis_prompt, context) { full_prompt <- paste0(analysis_prompt, '\n\nContext:\n', jsonlite::toJSON(context, auto_unbox = TRUE)); response <- self(full_prompt); return(list(raw_response = response)) }, get_rate_limit_status = function() { list(rpm_used = length(private), rpm_limit = private) }, shutdown = function() { private <- FALSE }))
